import json, tempfile, os
from pathlib import Path
from ocean_sonar import product as P

def trend_item(index, failed_delta, coverage_delta, quality):
    return {"index": index, "failed_delta": failed_delta,
            "coverage_delta": coverage_delta, "quality": quality}

def product_section(quality="pass", coverage_delta=0.1):
    item = trend_item(1, 0, coverage_delta, quality)
    passed = 1 if quality == "pass" else 0
    return {"trend": {"changes": (item,), "worst": item, "quality": quality},
            "summary": {"count": 1, "passed": passed, "failed": 1-passed,
                        "coverage_delta": coverage_delta},
            "quality": quality}

def substrate_section(quality="pass"):
    reg = 0 if quality == "pass" else 1
    return {"count": 2, "changes": 1, "regressed": reg, "unknown_delta": 0,
            "unknown_ratio_delta": 0.0, "worst": (1, 0, 0.0, quality),
            "quality": quality}

def crosspoint_section(quality="pass"):
    reg = 0 if quality == "pass" else 1
    fd = 1 if quality == "fail" else 0
    return {"sources": ["a.json","b.json"],
            "trend": {"count": 2, "2"})

with tempfile.TemporaryDirectory() as d:
    d = Path(d)
    def write_overview(sec, name):
        P.quality_dashboard = lambda path, sec=sec: sec[0]
        P.substrate.load_aggregate_report_trend = lambda path, sec=sec: sec[1]
        P.crosspoint.load_audit_report_trend = lambda path, sec=sec: sec[2]
        p = d / name; p.write_bytes(P.serialize_overview("p.json","s.json","c.json"))
        return str(p)

    a = write_overview((product_section("pass"), substrate_section("pass"), crosspoint_section("pass")), "ovA.json")
    b = write_overview((product_section("fail", -0.2), substrate_section("fail"), crosspoint_section("fail")), "ovB.json")

    # report0 from trend A->B (regressed increased, pass fails)
    t0 = d / "trend0.json"; P.export_overview_trend([a, b], str(t0))
    r0 = d / "report0.json"; P.export_overview_trend_report(str(t0), str(r0))
    # report1 from trend B->B (all pass)
    t1 = d / "trend1.json"; P.export_overview_trend([b, b], str(t1))
    r1 = d / "report1.json"; P.export_overview_trend_report(str(t1), str(r1))

    raw = P.serialize_overview_comparison([str(r0), str(r1)])
    print("canonical:", raw.decode())
    out = d / "comparison.json"
    B = P.export_overview_comparison([str(r0), str(r1)], str(out))
    assert B == raw and out.read_bytes() == raw
    print(P.render_overview_comparison(str(out)))
    try:
