    except Exception as e:
        print("paths-first:", type(e).__name__, e)
    try:
        P.export_overview_comparison([str(r0), str(r1)], 123)
    except Exception as e:
        print("output-type:", type(e).__name__, e)
    try:
        P.export_overview_comparison([str(r0), str(r1)], str(r0))
    except Exception as e:
        print("overlap:", type(e).__name__, e)
    try:
        P.render_overview_comparison(123)
    except Exception as e:
        print("render-path:", type(e).__name__, e)
